/// <summary>
/// extension of FormControl AVACustAccount
/// </summary>
[ExtensionOf(formControlStr(SalesTableListPage, AVACustAccount))]
final class AVASalesTableListPageFrmCtr_AVACustAccount_Extension
{
}

Method.Source:
/// <summary>
/// AVA
/// </summary>
/// <returns>boolean</returns>
public boolean modified()
{
    boolean ret = next modified();

    FormDataSource avaSalesTable_ds = this.formRun().dataSource(tableStr(SalesTable));
    CustAccount custAccountLoc = this.valueStr();

    if (custAccountLoc)
    {
        SysQuery::findOrCreateRange(avaSalesTable_ds.queryBuildDataSource(), fieldNum(SalesTable, CustAccount)).value(queryValue(custAccountLoc));
    }
    else
    {
        SysQuery::findOrCreateRange(avaSalesTable_ds.queryBuildDataSource(), fieldNum(SalesTable, CustAccount)).value(SysQueryRangeUtil::valueUnlimited());
    }

    avaSalesTable_ds.executeQuery();

    return ret;
}
